<?php
session_start();
require __DIR__ . '/config.php';
require_admin();
$pdo = db();
$linkId = filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT) ?: 0;
if ($linkId) {
    $s=$pdo->prepare('SELECT * FROM tracking_links WHERE id=?'); $s->execute([$linkId]); $selected=$s->fetch();
    if (!$selected) { http_response_code(404); exit('Link not found.'); }
    $s=$pdo->prepare('SELECT * FROM location_reports WHERE link_id=? ORDER BY reported_at DESC'); $s->execute([$linkId]); $reports=$s->fetchAll();
} else {
    $selected=null;
    $reports=$pdo->query('SELECT r.*,l.label,l.token FROM location_reports r JOIN tracking_links l ON l.id=r.link_id ORDER BY r.reported_at DESC')->fetchAll();
}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Location reports · Pinpoint</title><link rel="stylesheet" href="assets/style.css"></head><body class="app-body"><aside class="sidebar"><a class="brand" href="dashboard.php"><span class="brand-mark">P</span><span>pinpoint<span class="brand-dot">.</span><small>LOCATION LINKS</small></span></a><div class="side-label">WORKSPACE</div><a class="side-link" href="dashboard.php"><span>▦</span> Overview</a><a class="side-link" href="dashboard.php#links"><span>↗</span> Tracking links</a><a class="side-link active" href="reports.php"><span>⌖</span> Location reports</a><div class="sidebar-bottom"><div class="secure-card"><span class="secure-icon">✦</span><b>Privacy first</b><p>Only location shares approved by visitors are saved.</p></div><a class="side-link" href="logout.php"><span>↪</span> Sign out</a></div></aside><main class="main-content"><header class="topbar"><div><p class="eyebrow">YOUR WORKSPACE / REPORTS</p><h1>Location reports<span class="brand-dot">.</span></h1><p class="muted"><?= $selected ? 'Reports for '.e($selected['label']) : 'Every location report shared with permission.' ?></p></div><div class="top-actions"><a class="btn secondary" href="dashboard.php">← Dashboard</a></div></header><section class="panel"><div class="panel-heading"><div><p class="eyebrow">REPORT HISTORY</p><h2><?=count($reports)?> report<?=count($reports)===1?'':'s'?></h2></div></div><?php if(!$reports): ?><div class="empty-state"><div class="empty-icon">⌖</div><h3>No reports yet</h3><p>When someone chooses to share their device location, the coordinates will show up here.</p></div><?php else: ?><div class="table-wrap"><table><thead><tr><th>LINK</th><th>COORDINATES</th><th>ACCURACY</th><th>REPORTED</th><th>MAP</th></tr></thead><tbody><?php foreach($reports as $r): ?><tr><td><div class="link-name"><span class="link-icon">⌖</span><div><b><?=e($r['label'] ?? $selected['label'] ?? 'Location link')?></b><small>Report #<?=(int)$r['id']?></small></div></div></td><td class="coordinate-cell"><?=e($r['latitude'])?><br><?=e($r['longitude'])?></td><td><?= $r['accuracy_meters']===null?'Unknown':e((string)round((float)$r['accuracy_meters'])).' m' ?></td><td class="date-cell"><?=e(date('M j, Y · g:i a',strtotime($r['reported_at'])))?></td><td><a class="text-link" target="_blank" rel="noopener" href="https://www.google.com/maps?q=<?=rawurlencode($r['latitude'].','.$r['longitude'])?>">Open map ↗</a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section><footer class="app-footer"><span>© <?=date('Y')?> Pinpoint</span><span><span class="status-dot"></span> Privacy-first reports</span></footer></main></body></html>
